 const rgb=hex=>{const n=parseInt(hex.slice(1),16);return [(n>>16)&255,(n>>8)&255,n&255]};
 const tone=(hex,k)=>{const [r,g,b]=rgb(hex);return `rgb(${Math.min(255,Math.round(r*k))},${Math.min(255,Math.round(g*k))},${Math.min(255,Math.round(b*k))})`};
 const base=skin==='obsidian'?'#151923':skin==='ivory'?'#c3b18d':skin==='forged'?'#806044':'#173c31';
