function draw3DDice(){
 if(!diceCtx||!diceCanvas)return;
 // Render one clean die, then compose the same number of physical-looking dice
 // shown in the roll. The large result medallion remains above the group.
 drawSingleDie();
 const count=Math.max(1,Math.min(20,Number($("diceCount")?.value)||1));
 if(count===1)return;
 const source=document.createElement("canvas");source.width=diceCanvas.width;source.height=diceCanvas.height;
 source.getContext("2d").drawImage(diceCanvas,0,0);
 diceCtx.clearRect(0,0,diceCanvas.width,diceCanvas.height);
 const cols=count<=3?count:count<=6?3:4,rows=Math.ceil(count/cols);
 const cellW=diceCanvas.width/cols,cellH=diceCanvas.height/rows;
 const scale=count<=2?.76:count<=4?.61:count<=6?.49:.37;
 for(let i=0;i<count;i++){
  const col=i%cols,row=Math.floor(i/cols);
  const x=col*cellW+(cellW-source.width*scale)/2;
  const y=row*cellH+(cellH-source.height*scale)/2;
  diceCtx.drawImage(source,x,y,source.width*scale,source.height*scale);
 }
}
function animate3DDice(){if(!diceCanvas)return;dice3D.animating=true;const reduced=window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;const start=performance.now(),duration=reduced?30:1500;const initial={...dice3D};function frame(now){const t=Math.min(1,(now-start)/duration),ease=1-Math.pow(1-t,3);dice3D.rx=initial.rx+ease*7.5;dice3D.ry=initial.ry+ease*10.5;dice3D.rz=initial.rz+ease*4.8;draw3DDice();if(t<1)requestAnimationFrame(frame);else{dice3D.animating=false;dice3D.rx+=.08;draw3DDice();}}requestAnimationFrame(frame);}
