function renderDiceHistory(){
  const list=$("diceHistory");
  if(!diceHistory.length){list.innerHTML='<li class="dice-history-empty">No rolls yet. Your next throw starts the record.</li>';return;}
  list.innerHTML=diceHistory.map(r=>`<li><span class="history-die">${r.count}×D${r.sides}</span><span class="history-detail">${r.breakdown}</span><strong>${r.total}</strong></li>`).join("");
}
$("rollDice").addEventListener("click",()=>{
  const button=$("rollDice");if(button.disabled)return;
  const sides=Number($("diceType").value),count=Math.max(1,Math.min(20,Number($("diceCount").value)||1));
  const modifier=Math.max(-99,Math.min(99,Number($("diceModifier").value)||0));
  const rolls=Array.from({length:count},()=>Math.floor(Math.random()*sides)+1);
  const subtotal=rolls.reduce((a,b)=>a+b,0),total=subtotal+modifier;
  const breakdown=rolls.join(" + ")+(modifier?` ${modifier>0?"+":"−"} ${Math.abs(modifier)}`:"");
  const isCritical=sides===20&&count===1&&rolls[0]===20;
  const isFumble=sides===20&&count===1&&rolls[0]===1;
  const die=$("heroDie");die.classList.remove("critical","fumble");draw3DDice();animate3DDice();
  button.disabled=true;button.classList.add("is-rolling");$("diceStageCaption").textContent="THE DICE ARE IN MOTION…";
  $("diceResult").innerHTML='<span class="result-label">THE RESULT</span><strong>Rolling…</strong><small>Fate is deciding.</small>';
  const overlay=$("dieResultOverlay");overlay.classList.remove("show");overlay.querySelector("strong").textContent="…";
  window.setTimeout(()=>{
    if(isCritical)die.classList.add("critical");if(isFumble)die.classList.add("fumble");
    
    overlay.querySelector("span").textContent=isCritical?"NATURAL 20":isFumble?"NATURAL 1":"ROLL TOTAL";overlay.querySelector("strong").textContent=String(total);overlay.classList.add("show");
    $("diceStageCaption").textContent=isCritical?"NATURAL 20 · A LEGENDARY MOMENT":isFumble?"NATURAL 1 · THE FATES ARE CRUEL":`${count} D${sides}${count===1?"":"s"} · ROLL COMPLETE`;
    const tone=isCritical?"critical-result":isFumble?"fumble-result":"";
    $("diceResult").innerHTML=`<span class="result-label">${isCritical?"NATURAL 20":isFumble?"NATURAL 1":"TOTAL"}</span><strong class="${tone}">${total}</strong><small>${count>1?`${count} dice · `:""}Subtotal ${subtotal}${modifier?` · Modifier ${modifier>0?"+":""}${modifier}`:""}</small>`;
    $("diceBreakdown").textContent=`${rolls.map((v,i)=>`Die ${i+1}: ${v}`).join("  ·  ")}${modifier?`  ·  Modifier: ${modifier>0?"+":""}${modifier}`:""}  ·  Total: ${total}`;
    diceHistory.unshift({sides,count,breakdown,total});diceHistory=diceHistory.slice(0,8);renderDiceHistory();
    button.disabled=false;button.classList.remove("is-rolling");
  },1550);
});
