const sheetFields={level:"sheetLevel",background:"sheetBackground",alignment:"sheetAlignment",proficiency:"sheetProficiency",str:"sheetStr",dex:"sheetDex",con:"sheetCon",int:"sheetInt",wis:"sheetWis",cha:"sheetCha",hpCurrent:"sheetHpCurrent",hpMax:"sheetHpMax",hpTemp:"sheetHpTemp",ac:"sheetAc",speed:"sheetSpeed",initiative:"sheetInitiative",hitDice:"sheetHitDice",hitDiceRemaining:"sheetHitDiceRemaining",deathSuccesses:"sheetDeathSuccesses",deathFailures:"sheetDeathFailures",exhaustion:"sheetExhaustion",inspiration:"sheetInspiration",passivePerception:"sheetPassivePerception",saves:"sheetSaves",skills:"sheetSkills",attacks:"sheetAttacks",features:"sheetFeatures",inventory:"sheetInventory",spells:"sheetSpells",spellcasting:"sheetSpellcasting",spellAbility:"sheetSpellAbility",spellSlots:"sheetSpellSlots",equippedWeapon:"sheetEquippedWeapon",weaponAbility:"sheetWeaponAbility",equippedArmor:"sheetEquippedArmor",equippedShield:"sheetEquippedShield",weaponProficient:"sheetWeaponProficient",carriedGear:"sheetCarriedGear",conditions:"sheetConditions",notes:"sheetNotes"};
