function read5ESheet(){const out={};Object.entries(sheetFields).forEach(([key,id])=>{const el=$(id);out[key]=el.type==="number"?(el.value===""?null:Number(el.value)):el.type==="checkbox"?el.checked:el.value.trim()});out.proficiency=proficiencyForLevel(out.level);out.deathSuccesses=Math.max(0,Math.min(3,Number(out.deathSuccesses)||0));out.deathFailures=Math.max(0,Math.min(3,Number(out.deathFailures)||0));out.exhaustion=Math.max(0,Math.min(6,Number(out.exhaustion)||0));out.hitDiceRemaining=Math.max(0,Number(out.hitDiceRemaining)||0);const wis=abilityMod(out.wis);out.passivePerception=10+wis+(/\bperception\b/i.test(out.skills||"")?out.proficiency:0);if(out.spellAbility){out.spellSaveDC=8+out.proficiency+abilityMod(out[out.spellAbility]);out.spellAttackBonus=out.proficiency+abilityMod(out[out.spellAbility])}else{out.spellSaveDC=null;out.spellAttackBonus=null}const weapon=rulesLibraryEntries.find(x=>x.id===out.equippedWeapon),armor=rulesLibraryEntries.find(x=>x.id===out.equippedArmor),shield=rulesLibraryEntries.find(x=>x.id===out.equippedShield);out.weaponName=weapon?.title||"";out.weaponDamage=(weapon?.referenceFacts||[]).find(x=>/damage \/ ac/i.test(x[0]))?.[1]||"";out.weaponAttackBonus=weapon?(abilityMod(out[out.weaponAbility||"str"])+(out.weaponProficient?out.proficiency:0)):null;out.armorName=armor?.title||"";out.shieldName=shield?.title||"";out.calculatedAC=armor?calculateArmorClass(armor,out.dex,!!shield):null;if(out.calculatedAC!==null)out.ac=out.calculatedAC;return out}
