function updateSheetDerivedPreview(){const level=Number($("sheetLevel")?.value)||1,prof=proficiencyForLevel(level),ability=$("sheetSpellAbility")?.value,score=ability?Number($("sheet"+ability[0].toUpperCase()+ability.slice(1))?.value)||10:10;const mod=ability?abilityMod(score):0;const preview=$("sheetDerivedPreview");if($("sheetProficiency"))$("sheetProficiency").value=prof;if(preview)preview.textContent=ability?`Proficiency bonus +${prof} · Spell save DC ${8+prof+mod} · Spell attack ${signed(prof+mod)}`:`Proficiency bonus +${prof} · Choose a spellcasting ability to calculate spell statistics.`}
