// Dungeon Master's Toolkit — original generators and 2014 5E encounter estimates.
const TOOLKIT_KEY="gmk-dm-toolkit-notes-v1";
let toolkitNotes=(()=>{try{return JSON.parse(localStorage.getItem(TOOLKIT_KEY)||"[]")}catch{return []}})();
const pick=a=>a[Math.floor(Math.random()*a.length)];
const adventureParts={places:["a market town built around a sealed well","an abandoned watchtower above a trade road","a river crossing where travelers have begun to vanish","a remote monastery whose bells ring at midnight","a border village caught between rival houses","a ruined fortress reclaimed by the forest"],problems:["supplies are disappearing and no one agrees on who is responsible","a trusted local has returned with a story that cannot be true","an old agreement has been broken and both sides are preparing for war","strange lights have appeared where an ancient road once ran","a series of accidents suggests someone is testing the settlement's defenses","a valuable guest has vanished shortly before an important ceremony"],stakes:["the region's fragile peace","the safety of a group of missing children","the only safe route through the mountains","the reputation of a respected family","a harvest the settlement cannot afford to lose","the freedom of someone wrongly accused"],twists:["the apparent enemy is trying to prevent something worse","the clues point to two people working at cross purposes","the solution requires the party to choose who receives scarce help","the original account of the event was deliberately altered","the danger is real, but the person exploiting it is not its cause","an ally knows more than they have admitted"]};
const npcParts={roles:["a traveling healer","a disgraced household guard","a cheerful but watchful innkeeper","a junior archivist","a caravan master","a village reeve","a retired adventurer","a wandering performer","a minor noble's envoy","a reclusive craftsperson"],manner:["speaks softly and watches every doorway","uses humor to avoid personal questions","is formal even in casual conversation","never gives a direct answer when a story will do","is impatient with titles but remembers every favor","seems distracted by sounds others cannot hear","offers food or tea before discussing business","keeps correcting small details in other people's stories"],goals:["recover a family heirloom","protect a sibling from a dangerous choice","repay an old debt without revealing it","earn a place in a powerful guild","expose corruption in the local court","leave town before an old rival arrives","find the truth about a missing mentor","secure safe passage for a threatened community"],secrets:["has been passing information to a rival faction","is protecting someone the party has been hired to find","once made the same mistake they now condemn","possesses a map with one location deliberately removed","is being blackmailed over an old betrayal","has mistaken the party for people from their past","knows the local legend is based on a real event"]};
const siteParts={origins:["a royal garrison","a forgotten observatory","a sanctuary built over older ruins","a mine abandoned after a cave-in","a refuge constructed during a long-ago war","a trading post on a vanished road","a prison for a threat no one remembers"],purposes:["guard a passage","hide a dangerous object","study an unusual celestial event","shelter refugees","contain a spreading blight","protect a sealed chamber","serve as a meeting place for rival powers"],features:["its doors bear fresh scratches from the inside","a working mechanism still follows an unknown schedule","the walls are covered in names, some recently added","one chamber is untouched while the rest has collapsed","a nearby stream carries objects from far upstream","the oldest structure does not match the rest of the site"],threats:["a rival expedition has arrived first","the site is slowly becoming unstable","a guardian follows an order whose meaning has been lost","someone nearby is using the place for a private purpose","the environment changes after sunset","the site reacts to a particular symbol or spoken name"]};
function saveToolkitNote(type,title,body){toolkitNotes.unshift({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),type,title,body,date:new Date().toISOString()});toolkitNotes=toolkitNotes.slice(0,40);localStorage.setItem(TOOLKIT_KEY,JSON.stringify(toolkitNotes));renderToolkitNotes()}
function renderToolkitNotes(){const el=$("toolkitNotes");if(!el)return;if(!toolkitNotes.length){el.innerHTML='<div class="empty-state">Generated ideas you save will appear here.</div>';return}el.innerHTML=toolkitNotes.map(n=>`<article class="toolkit-note-item"><div><span class="tag">${escapeHTML(n.type)} · ${new Date(n.date).toLocaleDateString()}</span><h3>${escapeHTML(n.title)}</h3><p>${escapeHTML(n.body)}</p></div><button class="text-btn" data-delete-toolkit-note="${escapeHTML(n.id)}">Remove</button></article>`).join("")}
function generateAdventure(){const a=`Location: ${pick(adventureParts.places)}.\nProblem: ${pick(adventureParts.problems)}.\nWhat is at stake: ${pick(adventureParts.stakes)}.\nComplication: ${pick(adventureParts.twists)}.`;$("adventureResult").textContent=a;saveToolkitNote("ADVENTURE SEED","A new adventure",a)}
function generateNPC(){const n=`Role: ${pick(npcParts.roles)}.\nManner: ${pick(npcParts.manner)}.\nCurrent goal: ${pick(npcParts.goals)}.\nHidden complication: ${pick(npcParts.secrets)}.`;$("npcResult").textContent=n;saveToolkitNote("NPC CONCEPT","A character of the realm",n)}
function generateSite(){const n=`Formerly: ${pick(siteParts.origins)}.\nOriginal purpose: ${pick(siteParts.purposes)}.\nNotable feature: ${pick(siteParts.features)}.\nCurrent complication: ${pick(siteParts.threats)}.`;$("siteResult").textContent=n;saveToolkitNote("LOCATION CONCEPT","A forgotten place",n)}
const xpThresholds={1:[25,50,75,100],2:[50,100,150,200],3:[75,150,225,400],4:[125,250,375,500],5:[250,500,750,1100],6:[300,600,900,1400],7:[350,750,1100,1700],8:[450,900,1400,2100],9:[550,1100,1600,2400],10:[600,1200,1900,2800],11:[800,1600,2400,3600],12:[1000,2000,3000,4500],13:[1100,2200,3400,5100],14:[1250,2500,3800,5700],15:[1400,2800,4300,6400],16:[1600,3200,4800,7200],17:[2000,3900,5900,8800],18:[2100,4200,6300,9500],19:[2400,4900,7300,10900],20:[2800,5700,8500,12700]};
function calculateEncounter(){const levels=$("partyLevels").value.split(/[ ,;]+/).map(Number).filter(n=>Number.isInteger(n)&&n>=1&&n<=20);const count=Math.max(1,Math.min(30,Number($("monsterCount").value)||1));const xp=Number($("monsterCR").value);if(!levels.length){$("encounterResult").textContent="Enter at least one valid character level (1–20).";return}const thresholds=[0,0,0,0];levels.forEach(l=>xpThresholds[l].forEach((v,i)=>thresholds[i]+=v));const n=count;let mult=n===1?1:n===2?1.5:n<=6?2:n<=10?2.5:n<=14?3:4;let step=n===1?0:n===2?1:n<=6?2:n<=10?3:n<=14?4:5;if(levels.length<3)step=Math.min(5,step+1);else if(levels.length>=6)step=Math.max(0,step-1);mult=[1,1.5,2,2.5,3,4][step];const base=xp*n;const adjusted=Math.round(base*mult);const names=["Easy","Medium","Hard","Deadly"];let diff=adjusted<thresholds[0]?"Below easy":adjusted<thresholds[1]?"Easy":adjusted<thresholds[2]?"Medium":adjusted<thresholds[3]?"Hard":"Deadly";const result=`Party: ${levels.length} character(s), levels ${levels.join(", ")}.\nMonsters: ${count} · Base XP: ${base.toLocaleString()} · Adjusted XP: ${adjusted.toLocaleString()} (×${mult}).\nEstimated difficulty: ${diff}.\nParty thresholds — Easy ${thresholds[0].toLocaleString()} · Medium ${thresholds[1].toLocaleString()} · Hard ${thresholds[2].toLocaleString()} · Deadly ${thresholds[3].toLocaleString()}.`;$("encounterResult").textContent=result;saveToolkitNote("ENCOUNTER ESTIMATE",`${diff} encounter`,result)}
