function renderAdventureLinkOptions(c){const npcSel=$("adventureNpcLinks"),creatureSel=$("adventureCreatureLinks"),oldNpc=Array.from(npcSel.selectedOptions).map(o=>o.value),oldCr=Array.from(creatureSel.selectedOptions).map(o=>o.value);npcSel.innerHTML=(c.npcs||[]).map(n=>`<option value="${escapeHTML(n.id)}">${escapeHTML(n.name)}${n.role?" — "+escapeHTML(n.role):""}</option>`).join("");creatureSel.innerHTML=(c.customCreatures||[]).map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(x.name)}</option>`).join("");Array.from(npcSel.options).forEach(o=>o.selected=oldNpc.includes(o.value));Array.from(creatureSel.options).forEach(o=>o.selected=oldCr.includes(o.value))}
