function generateAdventureSpark(){const hooks=["A trusted courier arrives with a sealed message that appears to have been opened from the inside.","A familiar landmark has changed overnight, and only the oldest residents remember it differently.","A routine journey is interrupted by travelers who insist the party has already met them — years from now.","A local celebration stops when every bell in the district rings once, though none has been touched.","A missing expedition returns with one extra member whom nobody can remember inviting."];const objectives=["Discover who altered the truth and why before the next public gathering.","Reach the source of the disturbance and decide whether it should be contained, restored or destroyed.","Protect the people at risk while uncovering what the original expedition awakened.","Recover the missing evidence and determine who can be trusted with it."];const complications=["The apparent victim has concealed a crucial part of the story.","A rival group is pursuing the same goal for a defensible but conflicting reason.","The evidence points toward someone the party has reason to trust.","Solving the immediate problem may create a longer-term danger."];$("adventureHook").value=hooks[Math.floor(Math.random()*hooks.length)];$("adventureObjective").value=objectives[Math.floor(Math.random()*objectives.length)];$("adventureComplications").value=complications[Math.floor(Math.random()*complications.length)];if(!$("adventureTitle").value)$("adventureTitle").value=["The Unremembered Guest","Bells at Dusk","The Changed Landmark","A Message from Tomorrow","The Returning Company"][Math.floor(Math.random()*5)];$("adventureFormHeading").textContent="Shape this generated story spark";toast("An original adventure spark has been added to the form. Review and save it when ready.")}
