function openBestiaryDialog(kind,id){const c=bestiaryCampaign();if(!c){toast("Create or select a campaign first.");return}const arr=kind==="npc"?c.npcs||[]:c.customCreatures||[],v=id?arr.find(x=>x.id===id):null;$("bestiaryRecordForm").reset();$("bestiaryRecordId").value=id||"";$("bestiaryRecordKind").value=kind;$("bestiaryDialogTitle").textContent=(id?"Edit ":"Create ")+(kind==="npc"?"NPC dossier":"custom creature");$("bestiaryDialogEyebrow").textContent=kind==="npc"?"PERSON OF THE REALM":"CUSTOM STAT BLOCK";$("npcRecordFields").hidden=kind!=="npc";$("creatureRecordFields").hidden=kind!=="creature";$("bestiaryRecordName").value=v?.name||"";$("bestiaryRecordType").value=v?.role||v?.type||"";$("bestiaryRecordDisposition").value=v?.disposition||v?.size||"";
if(kind==="npc"){[["npcAppearance","appearance"],["npcMotivation","motivation"],["npcSecrets","secrets"],["npcNotes","notes"]].forEach(([a,b])=>$(a).value=v?.[b]||"")}else{[["creatureCR","cr"],["creatureXP","xp"],["creatureAC","ac"],["creatureHP","hp"],["creatureSpeed","speed"],["creatureInit","initiative"],["creatureAbilities","abilities"],["creatureTraits","traits"],["creatureActions","actions"],["creatureNotes","notes"]].forEach(([a,b])=>$(a).value=v?.[b]??({creatureXP:100,creatureAC:12,creatureHP:15,creatureSpeed:"30 ft.",creatureInit:0}[a]??""))}$("bestiaryRecordDialog").showModal()}
function saveBestiaryRecord(e){e.preventDefault();const c=bestiaryCampaign(),kind=$("bestiaryRecordKind").value,id=$("bestiaryRecordId").value||makeId();if(!c)return;const common={id,name:$("bestiaryRecordName").value.trim(),updated:new Date().toISOString()};let key,item;if(kind==="npc"){key="npcs";item={...common,role:$("bestiaryRecordType").value.trim(),disposition:$("bestiaryRecordDisposition").value.trim(),appearance:$("npcAppearance").value.trim(),motivation:$("npcMotivation").value.trim(),secrets:$("npcSecrets").value.trim(),notes:$("npcNotes").value.trim()}}else{key="customCreatures";item={...common,type:$("bestiaryRecordType").value.trim(),size:$("bestiaryRecordDisposition").value.trim(),cr:$("creatureCR").value.trim(),xp:Number($("creatureXP").value)||0,ac:Number($("creatureAC").value)||0,hp:Number($("creatureHP").value)||1,speed:$("creatureSpeed").value.trim(),initiative:Number($("creatureInit").value)||0,abilities:$("creatureAbilities").value.trim(),traits:$("creatureTraits").value.trim(),actions:$("creatureActions").value.trim(),notes:$("creatureNotes").value.trim()}}c[key]=c[key]||[];const i=c[key].findIndex(x=>x.id===id);if(i>=0)c[key][i]=item;else c[key].push(item);persistCampaigns();$("bestiaryRecordDialog").close();renderBestiary();toast("Record saved.")}
