function addEncounter(key,qty=1){const c=bestiaryCampaign();let x;if(key.startsWith("custom:")){x=(c?.customCreatures||[]).find(v=>v.id===key.slice(7));if(x)builtEncounter.push({name:x.name,xp:x.xp||0,qty,key})}else{x=rulesLibraryEntries.find(v=>v.id===key.slice(4));if(x)builtEncounter.push({name:x.title,xp:crXP(x.challengeRating),qty,key})}renderEncounterRoster()}
function renderEncounterRoster(){const el=$("encounterRoster");if(!el)return;el.innerHTML=builtEncounter.length?builtEncounter.map((x,i)=>`<div class="encounter-roster-row"><span>${escapeHTML(x.name)} <small>× ${x.qty} · ${x.xp.toLocaleString()} XP each</small></span><b>${(x.qty*x.xp).toLocaleString()} XP</b><button class="text-btn" data-remove-encounter="${i}">Remove</button></div>`).join(""):"<p class=\"muted\">No creatures added yet.</p>"}
function evaluateBuiltEncounter(){const levels=$("builderPartyLevels").value.split(/[ ,;]+/).map(Number).filter(x=>Number.isInteger(x)&&x>=1&&x<=20);if(!levels.length)return $("builtEncounterResult").textContent="Enter at least one valid party level (1–20).";if(!builtEncounter.length)return $("builtEncounterResult").textContent="Add at least one creature first.";const count=builtEncounter.reduce((n,x)=>n+x.qty,0),base=builtEncounter.reduce((n,x)=>n+x.qty*x.xp,0),t=[0,0,0,0];levels.forEach(l=>xpThresholds[l].forEach((v,i)=>t[i]+=v));let step=count===1?0:count===2?1:count<=6?2:count<=10?3:count<=14?4:5;if(levels.length<3)step=Math.min(5,step+1);else if(levels.length>=6)step=Math.max(0,step-1);const m=[1,1.5,2,2.5,3,4][step],adj=Math.round(base*m),d=adj<t[0]?"Below easy":adj<t[1]?"Easy":adj<t[2]?"Medium":adj<t[3]?"Hard":"Deadly";$("builtEncounterResult").textContent=`Party levels: ${levels.join(", ")}\nCreatures: ${builtEncounter.map(x=>`${x.name} × ${x.qty}`).join("; ")}\nBase XP: ${base.toLocaleString()} · Adjusted XP: ${adj.toLocaleString()} (×${m})\nEstimated difficulty: ${d}\nThresholds — Easy ${t[0]} · Medium ${t[1]} · Hard ${t[2]} · Deadly ${t[3]}\n\nEstimate only. Consider action economy, terrain, abilities and party resources.`;const c=bestiaryCampaign();if(c){c.savedEncounters=c.savedEncounters||[];c.savedEncounters.unshift({id:makeId(),date:new Date().toISOString(),roster:builtEncounter.map(x=>({...x})),result:$("builtEncounterResult").textContent});c.savedEncounters=c.savedEncounters.slice(0,30);persistCampaigns()}}
