$("bestiary-custom")?.addEventListener("click",e=>{const a=e.target.closest("[data-edit-creature]"),d=e.target.closest("[data-delete-creature]"),add=e.target.closest("[data-add-encounter]");if(a)openBestiaryDialog("creature",a.dataset.editCreature);if(d&&confirm("Delete this custom creature?")){const c=bestiaryCampaign();c.customCreatures=c.customCreatures.filter(x=>x.id!==d.dataset.deleteCreature);persistCampaigns();renderBestiary()}if(add){addEncounter(add.dataset.addEncounter);document.querySelector('[data-bestiary-tab="encounters"]').click()}});
$("bestiary-reference")?.addEventListener("click",e=>{const a=e.target.closest("[data-add-encounter]");if(a){addEncounter(a.dataset.addEncounter);document.querySelector('[data-bestiary-tab="encounters"]').click()}});$("addEncounterCreature")?.addEventListener("click",()=>{const v=$("encounterCreatureSelect").value;if(v)addEncounter(v,Math.max(1,Math.min(30,Number($("encounterCreatureQty").value)||1)))});$("encounterRoster")?.addEventListener("click",e=>{const b=e.target.closest("[data-remove-encounter]");if(b){builtEncounter.splice(Number(b.dataset.removeEncounter),1);renderEncounterRoster()}});$("evaluateBuiltEncounter")?.addEventListener("click",evaluateBuiltEncounter);$("clearBuiltEncounter")?.addEventListener("click",()=>{builtEncounter=[];renderEncounterRoster();$("builtEncounterResult").textContent="Encounter cleared."});renderBestiary();


// Phase 3.14 — Spellbook & Equipment Integration (2014 5E)
function sgCampaign(){return campaigns.find(c=>c.id===$("spellgearCampaign")?.value)||null}
function sgCharacter(){const c=sgCampaign();return (c?.characters||[]).find(x=>x.id===$("spellgearCharacter")?.value)||null}
function sgEnsureCharacter(ch){if(!ch)return;ch.spellbook=Array.isArray(ch.spellbook)?ch.spellbook:[];ch.inventoryItems=Array.isArray(ch.inventoryItems)?ch.inventoryItems:[];ch.spellSlots=ch.spellSlots&&typeof ch.spellSlots==="object"?ch.spellSlots:{};for(let i=1;i<=9;i++){const k=String(i);if(!ch.spellSlots[k])ch.spellSlots[k]={max:0,used:0}}}
function sgItemFacts(x){return Object.fromEntries(x.referenceFacts||[])}
function sgEscape(v){return escapeHTML(String(v??""))}
function renderSpellGear(){const cs=$("spellgearCampaign"),oldC=cs.value;const rows=campaigns.filter(c=>c.universe===currentUniverse);cs.innerHTML=rows.map(c=>`<option value="${sgEscape(c.id)}">${sgEscape(c.name)}</option>`).join("");if(rows.some(c=>c.id===oldC))cs.value=oldC;const c=sgCampaign(),chSel=$("spellgearCharacter"),oldCh=chSel.value;chSel.innerHTML=(c?.characters||[]).map(ch=>`<option value="${sgEscape(ch.id)}">${sgEscape(ch.name)}</option>`).join("");if((c?.characters||[]).some(ch=>ch.id===oldCh))chSel.value=oldCh;const ch=sgCharacter();if(ch)sgEnsureCharacter(ch);$("spellgearCharacterStatus").textContent=ch?`${ch.name} · ${ch.role||ch.species||"Campaign character"} · Level ${ch.sheet?.level||1}`:"Choose a campaign and character. Create a character in Characters & NPCs if none are listed.";["sg-spellbook","sg-inventory"].forEach(id=>$(id).classList.toggle("sg-needs-character",!ch));renderCharacterSpellbook();renderCharacterInventory();renderSpellLibrary();renderEquipmentLibrary();renderCustomItems()}
function renderCharacterSpellbook(){const ch=sgCharacter(),el=$("characterSpellList");if(!ch){el.innerHTML=sgEmpty("Select a character to manage their spellbook.");$("spellSlotGrid").innerHTML="";return}sgEnsureCharacter(ch);const q=$("sgSpellSearch").value.toLowerCase();el.innerHTML=ch.spellbook.filter(x=>(`${x.name} ${x.level} ${x.school}`).toLowerCase().includes(q)).map(x=>`<article class="spellgear-row"><div class="spellgear-row-main"><div class="spellgear-kicker">${sgEscape(x.level||"Spell")} · ${sgEscape(x.school||"Unspecified school")}</div><h3>${sgEscape(x.name)}</h3><p>${sgEscape(x.summary||"")}</p><small>${sgEscape(x.castingTime||"")} · ${sgEscape(x.range||"")} · ${sgEscape(x.duration||"")}</small></div><label class="prepared-toggle"><input type="checkbox" data-spell-prepared="${sgEscape(x.id)}" ${x.prepared?"checked":""}> Prepared</label><button class="text-btn" data-remove-spell="${sgEscape(x.id)}">Remove</button></article>`).join("")||sgEmpty("No spells in this character's spellbook yet. Add spells from the Spell Library.");$("spellSlotGrid").innerHTML=Array.from({length:9},(_,i)=>{const n=i+1,v=ch.spellSlots[String(n)];return `<div class="spell-slot-cell"><b>Level ${n}</b><label>Max <input type="number" min="0" max="20" data-slot-max="${n}" value="${Number(v.max)||0}"></label><label>Used <input type="number" min="0" max="20" data-slot-used="${n}" value="${Number(v.used)||0}"></label><small>${Math.max(0,(Number(v.max)||0)-(Number(v.used)||0))} remaining</small></div>`}).join("")}
function renderCharacterInventory(){const ch=sgCharacter(),el=$("characterInventoryList");if(!ch){el.innerHTML=sgEmpty("Select a character to manage their inventory.");$("inventorySummary").textContent="";return}sgEnsureCharacter(ch);const q=$("sgInventorySearch").value.toLowerCase(),items=ch.inventoryItems.filter(x=>(`${x.name} ${x.category} ${x.rarity}`).toLowerCase().includes(q));const equipped=ch.inventoryItems.filter(x=>x.equipped).length;$("inventorySummary").innerHTML=`<span><b>${ch.inventoryItems.reduce((n,x)=>n+(Number(x.quantity)||0),0)}</b> total quantity</span><span><b>${equipped}</b> equipped</span><span><b>${ch.inventoryItems.length}</b> item types</span>`;el.innerHTML=items.map(x=>`<article class="spellgear-row"><div class="spellgear-row-main"><div class="spellgear-kicker">${sgEscape(x.category||"Equipment")}${x.rarity?" · "+sgEscape(x.rarity):""}</div><h3>${sgEscape(x.name)}</h3><p>${sgEscape(x.description||x.summary||"")}</p></div><label class="inventory-qty">Qty <input type="number" min="0" max="999" value="${Number(x.quantity)||1}" data-inventory-qty="${sgEscape(x.id)}"></label><label class="prepared-toggle"><input type="checkbox" data-item-equipped="${sgEscape(x.id)}" ${x.equipped?"checked":""}> Equipped</label><button class="text-btn" data-remove-inventory="${sgEscape(x.id)}">Remove</button></article>`).join("")||sgEmpty("No inventory items yet. Add gear from the Equipment Library or your custom items.")}
function sgEmpty(t){return `<div class="placeholder-panel spellgear-empty"><div class="placeholder-icon">✧</div><h3>${sgEscape(t)}</h3></div>`}
function sgAddSpell(entry){const ch=sgCharacter();if(!ch){toast("Select a character first.");return}sgEnsureCharacter(ch);if(ch.spellbook.some(x=>x.sourceId===entry.id)){toast("That spell is already in this spellbook.");return}ch.spellbook.push({id:makeId(),sourceId:entry.id,name:entry.title,level:entry.spellLevel||"Unspecified level",school:(entry.spellLevel||"").replace(/^\d+(st|nd|rd|th)-level\s*/i,""),castingTime:entry.castingTime||"",range:entry.range||"",duration:entry.duration||"",components:entry.components||"",summary:entry.summary||"",tableUse:entry.tableUse||"",prepared:false});persistCampaigns();renderCharacterSpellbook();toast("Spell added to character spellbook.")}
function sgAddInventory(entry,custom=false){const ch=sgCharacter();if(!ch){toast("Select a character first.");return}sgEnsureCharacter(ch);const id=makeId(),facts=sgItemFacts(entry);ch.inventoryItems.push({id,sourceId:entry.id||null,name:entry.title||entry.name,category:custom?(entry.category||"Custom item"):(/weapon/i.test(`${entry.title} ${entry.keywords}`)?"Weapon":/armor/i.test(`${entry.title} ${entry.keywords}`)?"Armor":/shield/i.test(entry.title)?"Shield":"Adventuring gear"),rarity:entry.rarity||"",quantity:1,equipped:false,description:entry.description||entry.summary||"",facts});persistCampaigns();renderCharacterInventory();toast("Item added to inventory.")}
function renderSpellLibrary(){const q=$("sgLibrarySpellSearch").value.toLowerCase(),a=rulesLibraryEntries.filter(x=>x.category==="Spells"&&(`${x.title} ${x.keywords} ${x.spellLevel||""}`).toLowerCase().includes(q));$("spellLibraryList").innerHTML=a.map(x=>`<article class="spellgear-card"><div class="spellgear-kicker">${sgEscape(x.spellLevel||"SPELL")}</div><h3>${sgEscape(x.title)}</h3><div class="spellgear-facts"><span>${sgEscape(x.castingTime||"—")}</span><span>${sgEscape(x.range||"—")}</span><span>${sgEscape(x.duration||"—")}</span></div><p>${sgEscape(x.summary||"")}</p><details><summary>Components &amp; table notes</summary><p><b>Components:</b> ${sgEscape(x.components||"Not specified")}</p><p>${sgEscape(x.tableUse||"")}</p></details><button class="secondary-btn" data-add-spell="${sgEscape(x.id)}">＋ Add to spellbook</button></article>`).join("")||sgEmpty("No matching spells in the current reference index.")}
function renderEquipmentLibrary(){const q=$("sgLibraryEquipmentSearch").value.toLowerCase(),type=$("sgEquipmentType").value,a=rulesLibraryEntries.filter(x=>x.category==="Equipment"&&(`${x.title} ${x.keywords}`).toLowerCase().includes(q)).filter(x=>type==="all"||(type==="weapon"&&/weapon/i.test(`${x.title} ${x.keywords}`))||(type==="armor"&&/armor/i.test(`${x.title} ${x.keywords}`))||(type==="shield"&&/shield/i.test(x.title))||(type==="gear"&&!/weapon|armor|shield/i.test(`${x.title} ${x.keywords}`)));$("equipmentLibraryList").innerHTML=a.map(x=>{const f=sgItemFacts(x);return `<article class="spellgear-card"><div class="spellgear-kicker">SRD 5.1 · EQUIPMENT</div><h3>${sgEscape(x.title)}</h3><p>${sgEscape(x.summary||"")}</p><div class="spellgear-facts">${(x.referenceFacts||[]).map(v=>`<span>${sgEscape(v[0])}: ${sgEscape(v[1])}</span>`).join("")}</div><p>${sgEscape(x.tableUse||"")}</p><button class="secondary-btn" data-add-equipment="${sgEscape(x.id)}">＋ Add to inventory</button></article>`}).join("")||sgEmpty("No matching equipment in the current reference index.")}
function renderCustomItems(){const c=sgCampaign(),el=$("customItemList");if(!c){el.innerHTML=sgEmpty("Select a campaign to view custom items.");return}c.customItems=Array.isArray(c.customItems)?c.customItems:[];el.innerHTML=c.customItems.map(x=>`<article class="spellgear-card"><div class="spellgear-kicker">${sgEscape(x.category)}${x.rarity?" · "+sgEscape(x.rarity):""}</div><h3>${sgEscape(x.name)}</h3><p>${sgEscape(x.description||"No description recorded.")}</p>${x.usage?`<small>${sgEscape(x.usage)}</small>`:""}<div class="spellgear-card-actions"><button class="secondary-btn" data-custom-to-inventory="${sgEscape(x.id)}">Add to character</button><button class="text-btn" data-delete-custom-item="${sgEscape(x.id)}">Delete</button></div></article>`).join("")||sgEmpty("No custom items yet. Create a campaign-specific magic item or treasure entry.")}
function saveCustomItem(e){e.preventDefault();const c=sgCampaign();if(!c){toast("Select a campaign first.");return}c.customItems=Array.isArray(c.customItems)?c.customItems:[];c.customItems.push({id:makeId(),name:$("customItemName").value.trim(),category:$("customItemCategory").value,rarity:$("customItemRarity").value.trim(),description:$("customItemDescription").value.trim(),usage:$("customItemUsage").value.trim(),created:new Date().toISOString()});persistCampaigns();$("customItemDialog").close();$("customItemForm").reset();renderCustomItems();toast("Custom item saved to campaign.")}
$("spellgearCampaign")?.addEventListener("change",renderSpellGear);$("spellgearCharacter")?.addEventListener("change",renderSpellGear);["sgSpellSearch","sgInventorySearch","sgLibrarySpellSearch","sgLibraryEquipmentSearch"].forEach(id=>$(id)?.addEventListener("input",()=>({sgSpellSearch:renderCharacterSpellbook,sgInventorySearch:renderCharacterInventory,sgLibrarySpellSearch:renderSpellLibrary,sgLibraryEquipmentSearch:renderEquipmentLibrary}[id])()));$("sgEquipmentType")?.addEventListener("change",renderEquipmentLibrary);
document.querySelectorAll("[data-sg-tab]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-sg-tab]").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".spellgear-panel").forEach(x=>x.classList.toggle("active",x.id===`sg-${b.dataset.sgTab}`))}));
$("spellLibraryList")?.addEventListener("click",e=>{const b=e.target.closest("[data-add-spell]");if(b){const x=rulesLibraryEntries.find(x=>x.id===b.dataset.addSpell);if(x)sgAddSpell(x)}});$("equipmentLibraryList")?.addEventListener("click",e=>{const b=e.target.closest("[data-add-equipment]");if(b){const x=rulesLibraryEntries.find(x=>x.id===b.dataset.addEquipment);if(x)sgAddInventory(x)}});
$("characterSpellList")?.addEventListener("change",e=>{const b=e.target.closest("[data-spell-prepared]");if(b){const ch=sgCharacter(),x=ch?.spellbook.find(x=>x.id===b.dataset.spellPrepared);if(x){x.prepared=b.checked;persistCampaigns();toast("Spell preparation updated.")}}});$("characterSpellList")?.addEventListener("click",e=>{const b=e.target.closest("[data-remove-spell]");if(b){const ch=sgCharacter();ch.spellbook=ch.spellbook.filter(x=>x.id!==b.dataset.removeSpell);persistCampaigns();renderCharacterSpellbook()}});
$("spellSlotGrid")?.addEventListener("change",e=>{const max=e.target.dataset.slotMax,used=e.target.dataset.slotUsed;if(!max&&!used)return;const ch=sgCharacter();if(!ch)return;sgEnsureCharacter(ch);const n=max||used,v=ch.spellSlots[n];if(max)v.max=Math.max(0,Math.min(20,Number(e.target.value)||0));if(used)v.used=Math.max(0,Math.min(v.max,Number(e.target.value)||0));persistCampaigns();renderCharacterSpellbook()});
$("characterInventoryList")?.addEventListener("change",e=>{const q=e.target.dataset.inventoryQty,eq=e.target.dataset.itemEquipped;if(!q&&!eq)return;const ch=sgCharacter(),x=ch?.inventoryItems.find(x=>x.id===(q||eq));if(!x)return;if(q)x.quantity=Math.max(0,Math.min(999,Number(e.target.value)||0));if(eq){x.equipped=e.target.checked;if(ch.sheet&&x.sourceId){const slot=/weapon/i.test(x.category)?"equippedWeapon":/armor/i.test(x.category)?"equippedArmor":/shield/i.test(x.category)?"equippedShield":null;if(slot){if(x.equipped)ch.sheet[slot]=x.sourceId;else if(ch.sheet[slot]===x.sourceId)ch.sheet[slot]=""}}}persistCampaigns();renderCharacterInventory()});$("characterInventoryList")?.addEventListener("click",e=>{const b=e.target.closest("[data-remove-inventory]");if(b){const ch=sgCharacter();ch.inventoryItems=ch.inventoryItems.filter(x=>x.id!==b.dataset.removeInventory);persistCampaigns();renderCharacterInventory()}});
$("customItemList")?.addEventListener("click",e=>{const add=e.target.closest("[data-custom-to-inventory]"),del=e.target.closest("[data-delete-custom-item]");const c=sgCampaign();if(add){const x=c.customItems.find(x=>x.id===add.dataset.customToInventory);if(x)sgAddInventory({...x,title:x.name,summary:x.description},true)}if(del&&confirm("Delete this custom item from the campaign library?")){c.customItems=c.customItems.filter(x=>x.id!==del.dataset.deleteCustomItem);persistCampaigns();renderCustomItems()}});
$("newCustomItem")?.addEventListener("click",()=>{if(!sgCampaign()){toast("Create or select a campaign first.");return}$("customItemDialog").showModal()});$("closeCustomItem")?.addEventListener("click",()=>$ ("customItemDialog").close());$("cancelCustomItem")?.addEventListener("click",()=>$ ("customItemDialog").close());$("customItemForm")?.addEventListener("submit",saveCustomItem);
renderSpellGear();


// Phase 3.17 — campaign worldbuilding
let editingPlaceId=null, editingFactionId=null;
function worldCampaign(){return campaigns.find(c=>c.id===$("worldCampaignSelect")?.value)||null}
function renderWorldWorkspace(){const sel=$("worldCampaignSelect");if(!sel)return;const old=sel.value,rows=campaignsForCurrentUniverse().slice().sort((a,b)=>a.name.localeCompare(b.name));sel.innerHTML=rows.map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.name)}</option>`).join("");if(rows.some(c=>c.id===old))sel.value=old;const c=worldCampaign(),has=!!c;$("worldNoCampaign").hidden=has;$("worldEditorWrap").hidden=!has;if(!has)return;c.places=Array.isArray(c.places)?c.places:[];c.factions=Array.isArray(c.factions)?c.factions:[];$("worldCounts").textContent=`${c.places.length} places · ${c.factions.length} factions`;renderWorldLists();renderCampaignMaps();renderWorldConnections()}
function renderWorldLists(){const c=worldCampaign();if(!c)return;const pq=$("placeSearch").value.toLowerCase(),fq=$("factionSearch").value.toLowerCase();$("placeList").innerHTML=c.places.filter(x=>`${x.name} ${x.type} ${x.description} ${x.connections}`.toLowerCase().includes(pq)).map(x=>`<article class="world-record-card"><div class="saved-adventure-top"><span class="tag">${escapeHTML(x.type||"PLACE")}</span><div><button class="secondary-btn" data-edit-place="${escapeHTML(x.id)}">Edit</button> <button class="text-btn" data-delete-place="${escapeHTML(x.id)}">Delete</button></div></div><h3>${escapeHTML(x.name)}</h3>${x.ruler?`<p><b>Authority:</b> ${escapeHTML(x.ruler)}</p>`:""}${x.description?`<p>${escapeHTML(x.description)}</p>`:""}${x.features?`<p><b>Notable:</b> ${escapeHTML(x.features)}</p>`:""}${x.connections?`<p><b>Connections:</b> ${escapeHTML(x.connections)}</p>`:""}${x.notes?`<details><summary>DM notes</summary><p>${escapeHTML(x.notes)}</p></details>`:""}</article>`).join("")||'<div class="placeholder-panel"><h3>No places recorded</h3><p>Add a settlement, region, landmark or other location to begin your campaign atlas.</p></div>';
$("factionList").innerHTML=c.factions.filter(x=>`${x.name} ${x.type} ${x.purpose} ${x.relations}`.toLowerCase().includes(fq)).map(x=>`<article class="world-record-card"><div class="saved-adventure-top"><span class="tag">${escapeHTML(x.type||"FACTION")}</span><div><button class="secondary-btn" data-edit-faction="${escapeHTML(x.id)}">Edit</button> <button class="text-btn" data-delete-faction="${escapeHTML(x.id)}">Delete</button></div></div><h3>${escapeHTML(x.name)}</h3>${x.leader?`<p><b>Leadership:</b> ${escapeHTML(x.leader)}</p>`:""}${x.purpose?`<p>${escapeHTML(x.purpose)}</p>`:""}${x.resources?`<p><b>Resources:</b> ${escapeHTML(x.resources)}</p>`:""}${x.relations?`<p><b>Allies & rivals:</b> ${escapeHTML(x.relations)}</p>`:""}${x.notes?`<details><summary>DM notes</summary><p>${escapeHTML(x.notes)}</p></details>`:""}</article>`).join("")||'<div class="placeholder-panel"><h3>No factions recorded</h3><p>Add a guild, order, government, company or other organization.</p></div>';
$("worldCounts").textContent=`${c.places.length} places · ${c.factions.length} factions`}
function resetPlaceForm(){$("placeForm").reset();$("placeId").value="";editingPlaceId=null;$("placeFormHeading").textContent="Add a place"}
function resetFactionForm(){$("factionForm").reset();$("factionId").value="";editingFactionId=null;$("factionFormHeading").textContent="Add a faction"}
// Phase 3.19 — explicit campaign relationship ledger
function worldConnectionRecords(c){const rows=[];const add=(type,arr)=> (arr||[]).forEach(x=>rows.push({id:x.id,type,name:x.name||x.title||"Untitled"}));add("Place",c.places);add("Faction",c.factions);add("NPC",c.npcs);add("Creature",c.customCreatures);add("Adventure",c.adventures);return rows}
function worldConnectionName(c,id){const r=worldConnectionRecords(c).find(x=>x.id===id);return r?`${r.name} · ${r.type}`:"[Record no longer exists]"}
function renderWorldConnections(){const c=worldCampaign();if(!c)return;c.worldConnections=Array.isArray(c.worldConnections)?c.worldConnections:[];const records=worldConnectionRecords(c),from=$("connectionFrom"),to=$("connectionTo");if(!from||!to)return;const priorFrom=from.value,priorTo=to.value;const opts=records.map(r=>`<option value="${escapeHTML(r.id)}">${escapeHTML(r.name)} · ${escapeHTML(r.type)}</option>`).join("");from.innerHTML=opts||'<option value="">Create campaign records first</option>';to.innerHTML=opts||'<option value="">Create campaign records first</option>';if(records.some(r=>r.id===priorFrom))from.value=priorFrom;if(records.some(r=>r.id===priorTo))to.value=priorTo;from.disabled=to.disabled=records.length<2;const q=($("connectionSearch")?.value||"").toLowerCase();const live=c.worldConnections.filter(x=>records.some(r=>r.id===x.fromId)&&records.some(r=>r.id===x.toId));const stale=c.worldConnections.length-live.length;$("connectionSummary").innerHTML=`<div class="connection-stat"><strong>${live.length}</strong><span>active connections</span></div><div class="connection-stat"><strong>${stale}</strong><span>links needing attention</span></div><div class="connection-stat"><strong>${records.length}</strong><span>available records</span></div>`;$("worldConnectionList").innerHTML=c.worldConnections.filter(x=>`${worldConnectionName(c,x.fromId)} ${x.type} ${worldConnectionName(c,x.toId)} ${x.notes||""}`.toLowerCase().includes(q)).map(x=>{const valid=records.some(r=>r.id===x.fromId)&&records.some(r=>r.id===x.toId);return `<article class="world-record-card connection-card ${valid?"":"connection-stale"}"><div class="saved-adventure-top"><span class="tag">${valid?"CAMPAIGN CONNECTION":"NEEDS ATTENTION"}</span><button type="button" class="text-btn" data-delete-world-connection="${escapeHTML(x.id)}">Remove</button></div><h3>${escapeHTML(worldConnectionName(c,x.fromId))}</h3><div class="connection-relation">${escapeHTML(x.type||"Connected to")}</div><h3>${escapeHTML(worldConnectionName(c,x.toId))}</h3>${x.notes?`<p>${escapeHTML(x.notes)}</p>`:""}</article>`}).join("")||'<div class="placeholder-panel"><h3>No connections recorded</h3><p>Create links between campaign places, factions, NPCs, creatures and adventures.</p></div>'}
function resetWorldConnectionForm(){$("worldConnectionForm")?.reset()}
$("worldConnectionForm")?.addEventListener("submit",e=>{e.preventDefault();const c=worldCampaign();if(!c)return;const fromId=$("connectionFrom").value,toId=$("connectionTo").value;if(!fromId||!toId||fromId===toId){toast("Choose two different campaign records.");return}c.worldConnections=Array.isArray(c.worldConnections)?c.worldConnections:[];if(c.worldConnections.some(x=>x.fromId===fromId&&x.toId===toId&&x.type===$("connectionType").value)){toast("That connection already exists.");return}c.worldConnections.unshift({id:makeId(),fromId,toId,type:$("connectionType").value,notes:$("connectionNotes").value.trim(),created:new Date().toISOString()});persistCampaigns();resetWorldConnectionForm();renderWorldConnections();toast("Campaign connection saved.")});
$("resetWorldConnection")?.addEventListener("click",resetWorldConnectionForm);$("connectionSearch")?.addEventListener("input",renderWorldConnections);$("worldConnectionList")?.addEventListener("click",e=>{const b=e.target.closest("[data-delete-world-connection]");if(!b)return;const c=worldCampaign();if(!c)return;c.worldConnections=(c.worldConnections||[]).filter(x=>x.id!==b.dataset.deleteWorldConnection);persistCampaigns();renderWorldConnections();toast("Connection removed.")});
$("worldCampaignSelect")?.addEventListener("change",()=>{resetPlaceForm();resetFactionForm();renderWorldWorkspace()});
$("placeForm")?.addEventListener("submit",e=>{e.preventDefault();const c=worldCampaign();if(!c)return;c.places=Array.isArray(c.places)?c.places:[];const x={id:editingPlaceId||makeId(),name:$("placeName").value.trim(),type:$("placeType").value,ruler:$("placeRuler").value.trim(),description:$("placeDescription").value.trim(),features:$("placeFeatures").value.trim(),connections:$("placeConnections").value.trim(),notes:$("placeNotes").value.trim(),updated:new Date().toISOString()};if(!x.name)return;const i=c.places.findIndex(v=>v.id===editingPlaceId);if(i>=0)c.places[i]=x;else c.places.unshift(x);persistCampaigns();resetPlaceForm();renderWorldLists();toast(i>=0?"Place updated.":"Place added to campaign atlas.")});
$("factionForm")?.addEventListener("submit",e=>{e.preventDefault();const c=worldCampaign();if(!c)return;c.factions=Array.isArray(c.factions)?c.factions:[];const x={id:editingFactionId||makeId(),name:$("factionName").value.trim(),type:$("factionType").value,leader:$("factionLeader").value.trim(),purpose:$("factionPurpose").value.trim(),resources:$("factionResources").value.trim(),relations:$("factionRelations").value.trim(),notes:$("factionNotes").value.trim(),updated:new Date().toISOString()};if(!x.name)return;const i=c.factions.findIndex(v=>v.id===editingFactionId);if(i>=0)c.factions[i]=x;else c.factions.unshift(x);persistCampaigns();resetFactionForm();renderWorldLists();toast(i>=0?"Faction updated.":"Faction added to campaign.")});
$("resetPlaceForm")?.addEventListener("click",resetPlaceForm);$("resetFactionForm")?.addEventListener("click",resetFactionForm);$("placeSearch")?.addEventListener("input",renderWorldLists);$("factionSearch")?.addEventListener("input",renderWorldLists);
$("placeList")?.addEventListener("click",e=>{const edit=e.target.closest("[data-edit-place]"),del=e.target.closest("[data-delete-place]");const c=worldCampaign();if(edit){const x=c.places.find(v=>v.id===edit.dataset.editPlace);if(!x)return;editingPlaceId=x.id;$("placeId").value=x.id;for(const [k,id] of Object.entries({name:"placeName",type:"placeType",ruler:"placeRuler",description:"placeDescription",features:"placeFeatures",connections:"placeConnections",notes:"placeNotes"}))$(id).value=x[k]||"";$("placeFormHeading").textContent="Edit place";$("placeForm").scrollIntoView({behavior:"smooth",block:"start"})}if(del&&confirm("Delete this place from the campaign atlas?")){c.places=c.places.filter(x=>x.id!==del.dataset.deletePlace);persistCampaigns();renderWorldLists();toast("Place deleted.")}});
$("factionList")?.addEventListener("click",e=>{const edit=e.target.closest("[data-edit-faction]"),del=e.target.closest("[data-delete-faction]");const c=worldCampaign();if(edit){const x=c.factions.find(v=>v.id===edit.dataset.editFaction);if(!x)return;editingFactionId=x.id;$("factionId").value=x.id;for(const [k,id] of Object.entries({name:"factionName",type:"factionType",leader:"factionLeader",purpose:"factionPurpose",resources:"factionResources",relations:"factionRelations",notes:"factionNotes"}))$(id).value=x[k]||"";$("factionFormHeading").textContent="Edit faction";$("factionForm").scrollIntoView({behavior:"smooth",block:"start"})}if(del&&confirm("Delete this faction from the campaign?")){c.factions=c.factions.filter(x=>x.id!==del.dataset.deleteFaction);persistCampaigns();renderWorldLists();toast("Faction deleted.")}});
document.querySelectorAll("[data-world-tab]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-world-tab]").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".world-tab-panel").forEach(x=>x.classList.toggle("active",x.id===`world-${b.dataset.worldTab}`));if(b.dataset.worldTab==="connections")renderWorldConnections()}));


// Phase 3.18 — campaign maps and geography (local image maps with atlas markers)
let activeCampaignMapId=null;
function mapCampaign(){return worldCampaign()}
function ensureCampaignMaps(c){if(c&&!Array.isArray(c.campaignMaps))c.campaignMaps=[];return c?.campaignMaps||[]}
function renderCampaignMaps(){const c=mapCampaign(),sel=$("campaignMapSelect"),stage=$("campaignMapStage"),legend=$("campaignMapMarkers"),del=$("deleteCampaignMap");if(!c||!sel)return;const maps=ensureCampaignMaps(c),old=activeCampaignMapId;sel.innerHTML=maps.map(m=>`<option value="${escapeHTML(m.id)}">${escapeHTML(m.title)} · ${escapeHTML(m.type)}</option>`).join("")||'<option value="">No maps uploaded</option>';if(maps.some(m=>m.id===old))sel.value=old;else{activeCampaignMapId=maps[0]?.id||null;sel.value=activeCampaignMapId||""}const map=maps.find(m=>m.id===activeCampaignMapId);del.disabled=!map;if(!map){stage.innerHTML='<div class="placeholder-panel"><h3>Your map room is waiting</h3><p>Upload a map above to begin placing locations.</p></div>';legend.innerHTML='<p class="muted">No map selected.</p>';return}map.markers=Array.isArray(map.markers)?map.markers:[];stage.innerHTML=`<div class="campaign-map-image-wrap" id="campaignMapImageWrap"><img src="${map.imageData}" alt="${escapeHTML(map.title)}" class="campaign-map-image">${map.markers.map((m,i)=>`<button type="button" class="campaign-map-pin" style="left:${m.x}%;top:${m.y}%" data-map-marker="${escapeHTML(m.id)}" title="${escapeHTML(m.label)}"><span>${i+1}</span></button>`).join("")}</div>`;legend.innerHTML=map.markers.map((m,i)=>`<article class="map-marker-entry"><span class="map-marker-number">${i+1}</span><div><strong>${escapeHTML(m.label)}</strong><small>${escapeHTML(m.placeName||m.note||"Map marker")}</small></div><button type="button" class="text-btn" data-remove-map-marker="${escapeHTML(m.id)}" aria-label="Remove ${escapeHTML(m.label)}">×</button></article>`).join("")||'<p class="muted">No markers yet. Click the map to add one.</p>'}
$("worldCampaignSelect")?.addEventListener("change",()=>{activeCampaignMapId=null;renderCampaignMaps()});
$("campaignMapSelect")?.addEventListener("change",e=>{activeCampaignMapId=e.target.value||null;renderCampaignMaps()});
$("campaignMapForm")?.addEventListener("submit",e=>{e.preventDefault();const c=mapCampaign(),file=$("campaignMapFile").files?.[0],title=$("campaignMapTitle").value.trim();if(!c||!file||!title)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)){toast("Please choose a PNG, JPG or WebP image.");return}if(file.size>12*1024*1024){toast("That image is too large. Please choose an image under 12 MB.");return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const max=1800,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);const imageData=canvas.toDataURL("image/jpeg",.82);const maps=ensureCampaignMaps(c),m={id:makeId(),title,type:$("campaignMapType").value,imageData,markers:[],width:canvas.width,height:canvas.height};maps.unshift(m);activeCampaignMapId=m.id;persistCampaigns();e.target.reset();renderCampaignMaps();toast("Map added to the campaign atlas.")};img.onerror=()=>toast("The selected image could not be read.");img.src=reader.result};reader.onerror=()=>toast("The selected image could not be loaded.");reader.readAsDataURL(file)});
$("campaignMapStage")?.addEventListener("click",e=>{const pin=e.target.closest("[data-map-marker]");if(pin){const c=mapCampaign(),m=ensureCampaignMaps(c).find(x=>x.id===activeCampaignMapId),marker=m?.markers.find(x=>x.id===pin.dataset.mapMarker);if(marker)toast(`${marker.label}${marker.placeName?" · "+marker.placeName:""}`);return}const wrap=e.target.closest("#campaignMapImageWrap");if(!wrap||e.target.closest(".campaign-map-pin"))return;const c=mapCampaign(),m=ensureCampaignMaps(c).find(x=>x.id===activeCampaignMapId);if(!m)return;const rect=wrap.getBoundingClientRect(),x=Math.max(0,Math.min(100,((e.clientX-rect.left)/rect.width)*100)),y=Math.max(0,Math.min(100,((e.clientY-rect.top)/rect.height)*100));const places=Array.isArray(c.places)?c.places:[];let label=prompt("Marker label (for example, North Gate):");if(!label||!label.trim())return;let placeName="",placeId="",note="";if(places.length){const choice=prompt("Optional: enter the exact name of a saved campaign place to link it. Leave blank to use a map note.");const linked=places.find(p=>p.name.toLowerCase()===String(choice||"").trim().toLowerCase());if(linked){placeId=linked.id;placeName=linked.name}else note=choice||""}else note=prompt("Optional map note:")||"";m.markers.push({id:makeId(),label:label.trim(),x,y,placeId,placeName,note});persistCampaigns();renderCampaignMaps();toast("Map marker added.")});
$("campaignMapMarkers")?.addEventListener("click",e=>{const b=e.target.closest("[data-remove-map-marker]");if(!b)return;const c=mapCampaign(),m=ensureCampaignMaps(c).find(x=>x.id===activeCampaignMapId);if(!m)return;m.markers=m.markers.filter(x=>x.id!==b.dataset.removeMapMarker);persistCampaigns();renderCampaignMaps()});
$("deleteCampaignMap")?.addEventListener("click",()=>{const c=mapCampaign(),maps=ensureCampaignMaps(c),m=maps.find(x=>x.id===activeCampaignMapId);if(!m||!confirm(`Delete the map “${m.title}” and its markers?`))return;c.campaignMaps=maps.filter(x=>x.id!==m.id);activeCampaignMapId=null;persistCampaigns();renderCampaignMaps();toast("Map deleted.")});


// Phase 3.22 — Combat Console (local, campaign-scoped encounter tracker)
const COMBAT_STORE_KEY="gmk-combat-console-v1";
let combatStore=(()=>{try{return JSON.parse(localStorage.getItem(COMBAT_STORE_KEY)||"{}")}catch{return {}}})();
let activeCombatId="";
function combatCampaign(){return campaigns.find(c=>c.id===$("combatCampaignSelect")?.value)||null}
function combatScopeKey(){const c=combatCampaign();return `${currentUniverse}:${c?.id||"local"}`}
function combatEncounters(){const c=combatCampaign();if(c){if(!Array.isArray(c.combatEncounters))c.combatEncounters=[];return c.combatEncounters}const k=combatScopeKey();if(!Array.isArray(combatStore[k]))combatStore[k]=[];return combatStore[k]}
function activeCombat(){return combatEncounters().find(x=>x.id===activeCombatId)||combatEncounters()[0]||null}
function saveCombatStore(){if(combatCampaign())persistCampaigns();else localStorage.setItem(COMBAT_STORE_KEY,JSON.stringify(combatStore))}
function renderCombatConsole(){
 const campaignSel=$("combatCampaignSelect"),encSel=$("combatEncounterSelect");if(!campaignSel||!encSel)return;
 const oldCampaign=campaignSel.value,rows=campaignsForCurrentUniverse().slice().sort((a,b)=>a.name.localeCompare(b.name));
 campaignSel.innerHTML='<option value="">Local encounter · no campaign</option>'+rows.map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.name)}</option>`).join("");
 if(rows.some(c=>c.id===oldCampaign))campaignSel.value=oldCampaign;
 const encounters=combatEncounters();if(!encounters.some(x=>x.id===activeCombatId))activeCombatId=encounters[0]?.id||"";
 encSel.innerHTML=encounters.map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(x.name)}</option>`).join("")||'<option value="">No saved encounters</option>';
 encSel.value=activeCombatId;
 const encounter=activeCombat();
 const chars=combatCampaign()?.characters||[];
 $("combatCharacterImport").innerHTML='<option value="">Choose a character…</option>'+chars.map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.name||"Unnamed character")}</option>`).join("");
 $("deleteCombatEncounter").disabled=!encounter;
 if(!encounter){$("combatRound").textContent="1";$("combatantCount").textContent="0 combatants";$("combatCurrentTurn").textContent="Create an encounter and add combatants to begin.";$("combatantList").innerHTML='<div class="combat-empty">No encounter selected. Create one to start tracking initiative and combat.</div>';return}
 encounter.combatants=Array.isArray(encounter.combatants)?encounter.combatants:[];
 $("combatRound").textContent=String(encounter.round||1);$("combatantCount").textContent=`${encounter.combatants.length} combatant${encounter.combatants.length===1?"":"s"}`;
 const ordered=encounter.combatants.slice().sort((a,b)=>(Number(b.initiative)||0)-(Number(a.initiative)||0));
 let currentIndex=ordered.findIndex(c=>c.id===encounter.currentTurnId);
 if(currentIndex<0){currentIndex=Math.max(0,Math.min(Number(encounter.turnIndex)||0,Math.max(0,ordered.length-1)));encounter.currentTurnId=ordered[currentIndex]?.id||"";}
 encounter.turnIndex=currentIndex;
 const current=ordered[currentIndex];
 $("combatCurrentTurn").textContent=current?`CURRENT TURN · ${current.name}${current.initiativeRolled?` · Initiative ${current.initiative}`:" · Roll initiative to establish order"}`:"Add combatants to prepare the encounter.";
 $("combatantList").innerHTML=ordered.length?ordered.map((x,i)=>{const hp=Math.max(0,Number(x.hp)||0),max=Math.max(1,Number(x.maxHp)||1),pct=Math.max(0,Math.min(100,hp/max*100)),active=current&&x.id===current.id;return `<article class="combatant-row ${active?"is-active":""} ${hp<=0?"is-defeated":""}" data-combatant-row="${escapeHTML(x.id)}"><div class="combat-init">${x.initiativeRolled?Number(x.initiative)||0:"—"}</div><div class="combat-name"><strong>${escapeHTML(x.name)}</strong><small>${escapeHTML((x.type||"enemy").replace(/^./,c=>c.toUpperCase()))}${x.ac!=null?` · AC ${Number(x.ac)}`:""}</small></div><div class="combat-stat"><small>HP</small><div class="hp-track"><span style="width:${pct}%"></span></div><b>${hp}/${max}</b></div><div class="combat-hp-controls"><button type="button" data-hp-delta="-1" data-id="${escapeHTML(x.id)}" aria-label="Remove one hit point">−</button><button type="button" data-hp-delta="1" data-id="${escapeHTML(x.id)}" aria-label="Restore one hit point">+</button><button type="button" data-hp-edit="${escapeHTML(x.id)}" aria-label="Edit hit points">✎</button></div><div class="combat-stat"><small>AC</small><b>${x.ac??"—"}</b></div><div class="combat-conditions" title="${escapeHTML(x.conditions||"No conditions")}">${escapeHTML(x.conditions||"No conditions")}</div><div class="combat-row-actions"><button type="button" data-condition="${escapeHTML(x.id)}" title="Set conditions" aria-label="Set conditions">☼</button><button type="button" data-remove-combatant="${escapeHTML(x.id)}" title="Remove combatant" aria-label="Remove combatant">×</button></div></article>`}).join(""):'<div class="combat-empty">No combatants yet. Add a character, ally, or enemy to begin.</div>';
}
function createCombatEncounter(){const name=prompt("Name this encounter:","New Encounter");if(!name||!name.trim())return;const list=combatEncounters(),item={id:makeId(),name:name.trim().slice(0,70),round:1,turnIndex:0,combatants:[],created:new Date().toISOString()};list.unshift(item);activeCombatId=item.id;saveCombatStore();renderCombatConsole();toast("Encounter created.")}
$("combatCampaignSelect")?.addEventListener("change",()=>{activeCombatId="";renderCombatConsole()});
$("combatEncounterSelect")?.addEventListener("change",e=>{activeCombatId=e.target.value;renderCombatConsole()});
$("newCombatEncounter")?.addEventListener("click",createCombatEncounter);
$("deleteCombatEncounter")?.addEventListener("click",()=>{const x=activeCombat();if(!x||!confirm(`Delete encounter “${x.name}”?`))return;const list=combatEncounters();const index=list.findIndex(v=>v.id===x.id);if(index>=0)list.splice(index,1);activeCombatId="";saveCombatStore();renderCombatConsole();toast("Encounter deleted.")});
$("combatantForm")?.addEventListener("submit",e=>{e.preventDefault();let x=activeCombat();if(!x){createCombatEncounter();x=activeCombat();if(!x)return}const hp=Math.max(0,Number($("combatantHP").value)||0);x.combatants.push({id:makeId(),name:$("combatantName").value.trim(),type:$("combatantType").value,initiativeBonus:Number($("combatantInit").value)||0,initiative:0,initiativeRolled:false,hp,maxHp:hp,ac:Math.max(0,Number($("combatantAC").value)||0),conditions:""});e.target.reset();$("combatantHP").value="10";$("combatantAC").value="12";$("combatantInit").value="0";saveCombatStore();renderCombatConsole();toast("Combatant added.")});
$("importCombatCharacter")?.addEventListener("click",()=>{const c=combatCampaign(),ch=c?.characters.find(x=>x.id===$("combatCharacterImport").value);if(!ch){toast("Choose a campaign character to import.");return}let x=activeCombat();if(!x){const name=prompt("Name this encounter:","New Encounter");if(!name)return;x={id:makeId(),name:name.trim(),round:1,turnIndex:0,combatants:[]};combatEncounters().unshift(x);activeCombatId=x.id}const sh=ch.sheet||{},hp=Math.max(0,Number(sh.hpCurrent??sh.hpMax)||0),max=Math.max(1,Number(sh.hpMax)||hp||1);x.combatants.push({id:makeId(),name:ch.name,type:"player",initiativeBonus:Number(sh.initiative)||0,initiative:0,initiativeRolled:false,hp,maxHp:max,ac:Number(sh.ac)||10,conditions:""});saveCombatStore();renderCombatConsole();toast(`${ch.name} added to the encounter.`)});
$("rollInitiative")?.addEventListener("click",()=>{const x=activeCombat();if(!x||!x.combatants.length){toast("Add combatants first.");return}x.combatants.forEach(c=>{c.initiative=1+Math.floor(Math.random()*20)+(Number(c.initiativeBonus)||0);c.initiativeRolled=true});x.combatants.sort((a,b)=>b.initiative-a.initiative);x.turnIndex=0;x.currentTurnId=x.combatants[0]?.id||"";x.round=1;saveCombatStore();renderCombatConsole();toast("Initiative rolled.")});
$("nextCombatTurn")?.addEventListener("click",()=>{const x=activeCombat();if(!x||!x.combatants.length){toast("Add combatants first.");return}const living=x.combatants.filter(c=>(Number(c.hp)||0)>0);if(!living.length){toast("No active combatants remain.");return}const order=x.combatants.slice().sort((a,b)=>(Number(b.initiative)||0)-(Number(a.initiative)||0));let idx=order.findIndex(c=>c.id===x.currentTurnId);if(idx<0)idx=Math.max(0,Math.min(Number(x.turnIndex)||0,order.length-1));let next=idx;for(let tries=0;tries<order.length;tries++){next=(next+1)%order.length;if(Number(order[next].hp)>0)break}if(next<=idx)x.round=Math.max(1,Number(x.round)||1)+1;x.turnIndex=next;x.currentTurnId=order[next].id;saveCombatStore();renderCombatConsole()});
$("combatantList")?.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;const x=activeCombat();if(!x)return;const id=b.dataset.id||b.dataset.hpEdit||b.dataset.condition||b.dataset.removeCombatant,c=x.combatants.find(v=>v.id===id);if(b.dataset.hpDelta&&c){c.hp=Math.max(0,Math.min(Number(c.maxHp)||9999,(Number(c.hp)||0)+Number(b.dataset.hpDelta)));saveCombatStore();renderCombatConsole();return}if(b.dataset.hpEdit&&c){const val=prompt(`Set current HP for ${c.name} (maximum ${c.maxHp}):`,String(c.hp));if(val===null)return;c.hp=Math.max(0,Math.min(Number(c.maxHp)||9999,Number(val)||0));saveCombatStore();renderCombatConsole();return}if(b.dataset.condition&&c){const val=prompt(`Conditions or effects for ${c.name}:`,c.conditions||"");if(val===null)return;c.conditions=val.trim().slice(0,180);saveCombatStore();renderCombatConsole();return}if(b.dataset.removeCombatant&&confirm(`Remove ${c?.name||"this combatant"} from the encounter?`)){x.combatants=x.combatants.filter(v=>v.id!==id);if(x.currentTurnId===id)x.currentTurnId="";x.turnIndex=Math.max(0,Math.min(x.turnIndex||0,x.combatants.length-1));saveCombatStore();renderCombatConsole()}});
renderCombatConsole();
